SOLEUR_OP_LIB_BAKED="/home/jean/.local/share/devin/cli/plugins/cache/github.com_jikig-ai_soleur_plugins_soleur-5a09ea60/0.0.0-unversioned/scripts/lib/operator-script.sh"

# Resolution order, most explicit first:
