# --- configuration -----------------------------------------------------------
SLUG="${SLUG:-linkedin-token-renewal}"
ENV_FILE="${ENV_FILE:-${SCRIPT_DIR}/.env}"
: "${SOLEUR_BOOTSTRAP_LEDGER:=${SCRIPT_DIR}/bootstrap-runs.jsonl}"
export SOLEUR_BOOTSTRAP_LEDGER
TOTAL_STAGES=4

usage() {
  cat <<USAGE
Usage: bootstrap.sh [--reset <KEY>] [--help]

  --reset <KEY>   Forget a persisted .env value so the next run re-asks for it.
                  A wrong credential is otherwise permanent: the value is stored
                  before it can be validated, and the environment-first ladder
                  means a re-run never re-prompts.
  --help          This text.

Environment:
  SOLEUR_BOOTSTRAP_LEDGER=<path>     Run ledger (default: beside this script).
  SOLEUR_OP_LIB=<abs-path>           Override the library path baked at generation.

Skip variables — one per class-1/class-3 prompt in THIS script, derived from
its source so the list cannot drift (naming convention: SOLEUR_BOOTSTRAP_<WHAT>
for a value, SOLEUR_BOOTSTRAP_SKIP_<WHAT>_BARRIER for a barrier). The
destructive-write acknowledgement has NONE, by rule:
$(grep -oE '^[[:space:]]*soleur_op_(barrier|value) SOLEUR_BOOTSTRAP_[A-Z0-9_]+' "${BASH_SOURCE[0]}" | awk '{print "  " $2}' | sort -u)
USAGE
}

# --- argument validation -----------------------------------------------------
# Deliberately ABOVE the EXIT trap installed below: a usage error must print no
# "Stopped during stage" banner, and `--reset` is not a stage.
RESET_KEY=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --reset) RESET_KEY="${2:-}"; [[ -n "$RESET_KEY" ]] || { echo "Error: --reset needs a KEY" >&2; usage >&2; exit 1; }; shift 2 ;;
    --help|-h) usage; exit 0 ;;
    *) echo "Unknown argument: $1" >&2; usage >&2; exit 1 ;;
  esac
done

# --- the credentials file must be ignored by git ------------------------------
# This script lives in a TRACKED directory (SKILL.md §Where), and its .env holds
# live credentials. A .gitignore that does not cover it turns the founder's next
# `git add .` into a pushed token (review P1-1). Checked BEFORE the first write —
# `--reset` writes too — on the .env AND on the `.tmp.XXXXXX` sibling the upsert
# creates beside it, which a bare `.env` pattern does not cover. Outside a git
# work tree (or without git) there is nothing to commit, so the check passes.
#
# PROBE THE RESOLVED PATH — the writer does. `soleur_op_env_upsert` and
# `soleur_op_env_reset` both `readlink -f` before writing, so probing the link
# NAME asks git about a file the write never touches: a founder who symlinks
# .env at a shared credentials file gets an ignored name, a passing probe, and
# the value written to a target git reports as untracked-and-not-ignored. The
# `.tmp.XXXXXX` sibling is created beside the RESOLVED file too, so it is
# derived from the resolved path rather than from $ENV_FILE. Confirmed against
# a fixture; Guard 7's symlink rows pin it.
env_not_ignored() {
  local dir; dir="$(dirname "$1")"
  git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1 || return 1
  ! git -C "$dir" check-ignore -q "$1"
}
ENV_FILE_RESOLVED="$(readlink -f -- "$ENV_FILE" 2>/dev/null || printf '%s' "$ENV_FILE")"
for probe in "$ENV_FILE_RESOLVED" "${ENV_FILE_RESOLVED}.tmp.XXXXXX"; do
  if env_not_ignored "$probe"; then
    printf 'SOLEUR_BOOTSTRAP_ENV_NOT_IGNORED path=%s\n' "$probe"
    printf 'The credentials file would be committed. Add it to .gitignore first (a pattern such as .env* covers both the file and its temp sibling).\n'
    exit 64
  fi
done
unset probe

if [[ -n "$RESET_KEY" ]]; then
  soleur_op_env_reset "$ENV_FILE" "$RESET_KEY"
  soleur_op_green "Forgot ${RESET_KEY}. Re-run to be asked for it again."
  exit 0
fi

# --- terminal outcome --------------------------------------------------------
# ONE trap. On a non-zero exit inside a stage it tells the founder which stage
# stopped, that nothing else was changed, and the one command that resumes —
# and it settles the stage in the ledger as `failed` with the exit code, so the
# ledger can say something other than "ok" (review P2-12). A library refusal
# (INPUT_REQUIRED, ABORTED) has already printed its own marker and sentence and
# written its `run_halt` line before this fires; the trap adds the stage context.
SCRIPT_PATH="${SCRIPT_DIR}/$(basename "${BASH_SOURCE[0]}")"
CURRENT_STAGE_INDEX=0
CURRENT_STAGE_NAME=""
on_exit() {
  local rc=$?
  [[ "$rc" -ne 0 && "$CURRENT_STAGE_INDEX" -gt 0 ]] || return 0
  # "Nothing else was changed" is FALSE on one path the library documents: a
  # secret whose write returned 0 and whose read-back did not confirm it may be
  # live (SOLEUR_BOOTSTRAP_SECRET_VERIFY_FAILED). Telling the founder nothing
  # changed is precisely what stops them revoking it, so the library raises a
  # flag and this sentence defers to it.
  if [[ -n "${SOLEUR_OP_WRITE_MAY_HAVE_LANDED:-}" ]]; then
    printf 'Stopped during stage %s (%s). A credential may already have been written — check it and revoke it if you did not mean to. Run: bash %s — already-done steps are skipped.\n' \
      "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" "$SCRIPT_PATH"
  else
    printf 'Stopped during stage %s (%s). Nothing else was changed. Run: bash %s — already-done steps are skipped.\n' \
      "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" "$SCRIPT_PATH"
  fi
  soleur_op_stage_end "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" failed "$rc"
}
trap on_exit EXIT

# run_stage <index> <name> <function>
#   Begin/settle around every stage, and the context the EXIT trap reports.
run_stage() {
  CURRENT_STAGE_INDEX="$1"; CURRENT_STAGE_NAME="$2"
  soleur_op_stage_begin "$1" "$2"
  "$3"
  soleur_op_stage_end "$1" "$2" ok 0
  CURRENT_STAGE_INDEX=0; CURRENT_STAGE_NAME=""
}


# =============================================================================
# STAGES — LinkedIn OAuth token renewal (#7404 + #7606)
# =============================================================================
#
# The two expired secrets, the scopes each must be minted with, and the stores
# they live in:
#
#   Secret                        Scopes to select in the token generator
#   --------------------------    ----------------------------------------
#   LINKEDIN_ACCESS_TOKEN         openid, profile, w_member_social, email
#   LINKEDIN_ORG_ACCESS_TOKEN     openid, profile, w_member_social,
#                                 w_organization_social
#
#   Store                         Consumer
#   --------------------------    ----------------------------------------
#   GitHub Actions secrets        CI workflows (content publisher)
#   Doppler soleur/prd            the deployed app — env is downloaded at
#                                 container start, so a deploy is what picks
#                                 the new value up
#
# The weekly cron (Monday 11:00 UTC, cron-linkedin-token-check) re-checks both
# tokens against api.linkedin.com/v2/userinfo and auto-closes its own
# action-required issues once they pass. This script runs the SAME probe before
# anything is persisted, so a bad or wrong token is caught at paste time.

TOKEN_GENERATOR_URL="https://www.linkedin.com/developers/tools/oauth/token-generator?clientId=78wtm2wu15iikn"
LINKEDIN_USERINFO="https://api.linkedin.com/v2/userinfo"
LINKEDIN_ORG_ACLS="https://api.linkedin.com/v2/organizationalEntityAcls?q=roleAssignee&role=ADMINISTRATOR&state=APPROVED"
GH_REPO="jikig-ai/soleur"

# token_is_live <value> — the same probe the weekly cron runs: HTTP 2xx from
# /v2/userinfo. Never echoes the token. `--disable --noproxy '*'` and discarded
# curl stderr match the credentialed-request shape used by the repo's other
# LinkedIn scripts (the URL can appear in curl's own error output).
token_is_live() {
  local tok="$1" response code
  response="$(curl --disable --noproxy '*' -s -m 15 \
    -H "Authorization: Bearer ${tok}" \
    -w '\n%{http_code}' \
    "$LINKEDIN_USERINFO" 2>/dev/null)" || return 1
  code="$(printf '%s' "$response" | tail -1)"
  [[ "$code" =~ ^2[0-9][0-9]$ ]]
}

# doppler_token <NAME> — the current soleur/prd value, empty on any failure.
# This is the store the deployed app actually reads (the container env is
# downloaded from Doppler at container start), so it is the vendor-side truth
# for "is a live token already installed".
doppler_token() {
  doppler secrets get "$1" -p soleur -c prd --plain 2>/dev/null || true
}

# mint_or_reuse <SECRET-NAME> <SKIP-VAR> <scope-list>
#   Sets MINTED_TOKEN. Ladder: Doppler live value -> .env recorded value ->
#   credential entry. The entered token is verified BEFORE it is persisted
#   anywhere, so a wrong paste fails here rather than propagating.
MINTED_TOKEN=""
mint_or_reuse() {
  local name="$1" skipvar="$2" scopes="$3" tok=""
  MINTED_TOKEN=""

  tok="$(doppler_token "$name")"
  if [[ -n "$tok" ]] && token_is_live "$tok"; then
    soleur_op_yellow "  already satisfied: ${name} in Doppler soleur/prd passes the live check"
    MINTED_TOKEN="$tok"
    return 0
  fi

  if [[ -f "$ENV_FILE" ]]; then
    tok="$(sed -n "s/^${name}=//p" "$ENV_FILE" | head -1)"
    if [[ -n "$tok" ]] && token_is_live "$tok"; then
      soleur_op_yellow "  reusing the verified token a previous run recorded"
      MINTED_TOKEN="$tok"
      return 0
    fi
  fi

  echo "  ${name} is expired or missing. Mint a replacement:"
  echo "    1. In the page that just opened, select scopes: ${scopes}"
  echo "    2. Accept the redirect URL confirmation -> Request access token ->"
  echo "       sign in -> Allow"
  echo "    3. Copy the generated token"
  echo "    (automation: set ${skipvar} and re-run non-interactively)"
  soleur_op_open_url "$TOKEN_GENERATOR_URL"

  tok="$(soleur_op_skip_value "$skipvar")"
  if [[ -z "$tok" ]]; then
    [[ -t 0 ]] || soleur_op_input_required "$skipvar"
    read -rs -p "  Paste the new ${name}: " tok
    echo ""
  fi

  if ! token_is_live "$tok"; then
    soleur_op_red "  ${name} failed the live check — LinkedIn userinfo did not"
    soleur_op_red "  return 2xx. Nothing was written. Re-run to paste a"
    soleur_op_red "  different token."
    return 1
  fi
  soleur_op_green "  live check passed (LinkedIn userinfo 2xx)."

  soleur_op_env_upsert "$ENV_FILE" "$name" "$tok"
  # A re-minted token makes the gh-write marker from the previous token stale —
  # clear it so the persist step writes the NEW value, not skips on the old.
  soleur_op_env_reset "$ENV_FILE" "${name}_GH_SET" 2>/dev/null || true
  MINTED_TOKEN="$tok"
}

# persist_token <SECRET-NAME> <value>
#   Writes both stores. Each write sits behind its own per-command ack (a prod
#   mutation), and each store's "already satisfied" check runs first so a
#   re-run only asks for what is actually missing.
persist_token() {
  local name="$1" tok="$2" cur=""

  # --- GitHub Actions secret ---
  # GitHub never discloses a stored secret's value, so presence in the list
  # says nothing about liveness. The strongest signal that exists is the
  # marker written AFTER soleur_op_gh_secret_set's own read-back confirmed
  # the write landed.
  if [[ -f "$ENV_FILE" ]] && grep -aq "^${name}_GH_SET=" "$ENV_FILE"; then
    soleur_op_yellow "  already satisfied: ${name} write to GitHub secrets is recorded"
  else
    soleur_op_ack_or_die "  Write ${name} to GitHub Actions secrets (${GH_REPO})? Type 'yes': "
    soleur_op_gh_secret_set "$GH_REPO" "$name" "$tok" || return 1
    soleur_op_env_upsert "$ENV_FILE" "${name}_GH_SET" "$(date -u '+%Y-%m-%dT%H:%M:%SZ')"
    soleur_op_green "  GitHub Actions secret updated and read-back confirmed."
  fi

  # --- Doppler soleur/prd ---
  # Vendor-side check: a LIVE token already in the config makes the write
  # unnecessary; an expired or missing one is overwritten.
  cur="$(doppler_token "$name")"
  if [[ -n "$cur" ]] && token_is_live "$cur"; then
    soleur_op_yellow "  already satisfied: Doppler soleur/prd ${name} passes the live check"
  else
    soleur_op_ack_or_die "  Write ${name} to Doppler soleur/prd (the app's env source)? Type 'yes': "
    if ! printf '%s' "$tok" | doppler secrets set "$name" -p soleur -c prd --no-interactive >/dev/null 2>&1; then
      printf 'SOLEUR_BOOTSTRAP_DOPPLER_WRITE_FAILED name=%s\n' "$name"
      soleur_op_red "  doppler secrets set failed — check 'doppler configure' auth, then re-run."
      return 1
    fi
    cur="$(doppler_token "$name")"
    if [[ -z "$cur" ]]; then
      SOLEUR_OP_WRITE_MAY_HAVE_LANDED=1
      export SOLEUR_OP_WRITE_MAY_HAVE_LANDED
      printf 'SOLEUR_BOOTSTRAP_DOPPLER_VERIFY_FAILED name=%s\n' "$name"
      soleur_op_red "  the write returned 0 but the read-back is empty — check the config in Doppler."
      return 1
    fi
    soleur_op_green "  Doppler soleur/prd updated and read-back confirmed."
  fi
}

stage_1_personal() {
  mint_or_reuse "LINKEDIN_ACCESS_TOKEN" SOLEUR_BOOTSTRAP_LINKEDIN_ACCESS_TOKEN \
    "openid, profile, w_member_social, email" || return 1
  persist_token "LINKEDIN_ACCESS_TOKEN" "$MINTED_TOKEN"
}

stage_2_org() {
  mint_or_reuse "LINKEDIN_ORG_ACCESS_TOKEN" SOLEUR_BOOTSTRAP_LINKEDIN_ORG_ACCESS_TOKEN \
    "openid, profile, w_member_social, w_organization_social" || return 1

  # Advisory org-scope probe: userinfo only proves the token is alive, not that
  # it carries w_organization_social — the scope org posting needs. A 2xx here
  # lists the Company Pages the token can administer/post to. A non-2xx is a
  # WARNING, not a stage failure: the decisive check is the same userinfo probe
  # the weekly cron runs, and this endpoint's scope requirements differ by app.
  if [[ -n "$MINTED_TOKEN" ]]; then
    local acl_code acl_body
    acl_body="$(curl --disable --noproxy '*' -s -m 15 \
      -H "Authorization: Bearer ${MINTED_TOKEN}" \
      -w '\n%{http_code}' \
      "$LINKEDIN_ORG_ACLS" 2>/dev/null)" || acl_body=""
    acl_code="$(printf '%s' "$acl_body" | tail -1)"
    if [[ "$acl_code" =~ ^2[0-9][0-9]$ ]]; then
      soleur_op_green "  org-scope probe passed (organizationalEntityAcls 2xx)."
    else
      soleur_op_yellow "  WARNING: org-scope probe returned ${acl_code:-<no response>} — if org"
      soleur_op_yellow "  posting still fails after deploy, re-mint the token and confirm"
      soleur_op_yellow "  w_organization_social was selected in the generator."
    fi
  fi

  persist_token "LINKEDIN_ORG_ACCESS_TOKEN" "$MINTED_TOKEN"
}

stage_3_env_refresh() {
  echo "  The app reads Doppler once — at container start. The new tokens reach"
  echo "  the running app on the NEXT deploy; LinkedIn posting stays down until then."
  echo ""
  echo "  Any merge to main deploys. To refresh right now, this stage can dispatch"
  echo "  a patch release (build + deploy, a few minutes):"
  echo "    gh workflow run web-platform-release.yml -f bump_type=patch"
  echo ""

  # Already dispatched in a previous run? Check that run's state.
  if [[ -f "$ENV_FILE" ]] && grep -aq '^DEPLOY_RUN_ID=' "$ENV_FILE"; then
    local run_id conclusion
    run_id="$(sed -n 's/^DEPLOY_RUN_ID=//p' "$ENV_FILE" | head -1)"
    conclusion="$(gh run view "$run_id" -R "$GH_REPO" --json conclusion,status \
      --jq '"\(.status)/\(.conclusion // "pending")"' 2>/dev/null || echo "unknown")"
    if [[ "$conclusion" == "completed/success" ]]; then
      soleur_op_yellow "  already satisfied: dispatched release ${run_id} deployed successfully"
      return 0
    fi
    soleur_op_yellow "  release ${run_id} is ${conclusion} — re-check after it completes"
    [[ "$conclusion" == in_progress/* || "$conclusion" == queued/* ]] && return 0
    soleur_op_env_reset "$ENV_FILE" DEPLOY_RUN_ID 2>/dev/null || true
  fi

  local choice=""
  soleur_op_value SOLEUR_BOOTSTRAP_DEPLOY_CHOICE "  Dispatch a patch release now? [yes/defer]: " choice
  if [[ "$choice" != "yes" ]]; then
    soleur_op_yellow "  deferred — the next merge to main deploys with the new env."
    soleur_op_yellow "  The weekly token check closes #7404 and #7606 after that deploy."
    return 0
  fi

  soleur_op_ack_or_die "  Run a production deploy (gh workflow run web-platform-release.yml -f bump_type=patch)? Type 'yes': "
  if ! gh workflow run web-platform-release.yml -R "$GH_REPO" -f bump_type=patch >/dev/null 2>&1; then
    soleur_op_red "  workflow dispatch failed — check 'gh auth status', then re-run."
    return 1
  fi
  sleep 5
  local new_run
  new_run="$(gh run list -R "$GH_REPO" --workflow web-platform-release.yml \
    --event workflow_dispatch -L 1 --json databaseId --jq '.[0].databaseId' 2>/dev/null || echo "")"
  if [[ -n "$new_run" ]]; then
    soleur_op_env_upsert "$ENV_FILE" DEPLOY_RUN_ID "$new_run"
    soleur_op_green "  dispatched release run ${new_run} — 'gh run watch ${new_run} -R ${GH_REPO}' to follow it."
  else
    soleur_op_green "  dispatched — could not capture the run id; check 'gh run list --workflow web-platform-release.yml'."
  fi
}

stage_4_verify() {
  local failed=0 name cur
  for name in LINKEDIN_ACCESS_TOKEN LINKEDIN_ORG_ACCESS_TOKEN; do
    cur="$(doppler_token "$name")"
    if [[ -n "$cur" ]] && token_is_live "$cur"; then
      soleur_op_green "  ${name}: live in Doppler soleur/prd (userinfo 2xx)"
    else
      soleur_op_red "  ${name}: not live in Doppler soleur/prd"
      failed=1
    fi
  done
  for name in LINKEDIN_ACCESS_TOKEN LINKEDIN_ORG_ACCESS_TOKEN; do
    if gh secret list -R "$GH_REPO" 2>/dev/null | grep -qE "^${name}[[:space:]]"; then
      soleur_op_green "  ${name}: present in GitHub Actions secrets"
    else
      soleur_op_red "  ${name}: missing from GitHub Actions secrets"
      failed=1
    fi
  done
  [[ "$failed" -eq 0 ]] || { soleur_op_red "  verification failed — re-run to complete the missing writes."; return 1; }

  echo ""
  echo "  Closeout is automatic: the weekly token check (Monday 11:00 UTC) calls"
  echo "  userinfo against the app's env and auto-closes #7404 and #7606 once a"
  echo "  deploy has picked the new values up. To close sooner, after the deploy:"
  echo "    soleur:trigger-cron  ->  cron/linkedin-token-check.manual-trigger"
}

main() {
  soleur_op_require_bins grep sed date mktemp printenv curl gh doppler
  soleur_op_ledger_init "$TOTAL_STAGES" "bootstrap.sh"

  # No resume index: every stage's precondition makes a re-run from stage 1
  # skip what is already done, so re-run IS resume.
  run_stage 1 "LINKEDIN_ACCESS_TOKEN — mint, verify, install" stage_1_personal
  run_stage 2 "LINKEDIN_ORG_ACCESS_TOKEN — mint, verify, install" stage_2_org
  run_stage 3 "refresh the deployed app's env" stage_3_env_refresh
  run_stage 4 "verify both stores" stage_4_verify

  soleur_op_summary_begin "BOOTSTRAP COMPLETE."
  soleur_op_summary_line "Both tokens verified live and installed in GitHub secrets + Doppler soleur/prd."
